"use strict";exports.id=4027,exports.ids=[4027],exports.modules={64027:(a,b,c)=>{c.d(b,{_0:()=>f,Mt:()=>g,jA:()=>h,U1:()=>i,DZ:()=>k,Mv:()=>j});let d=JSON.parse('[{"id":"booking-randomforest","name":"Booking \xb7 Random Forest + PCA","icon":"\uD83C\uDF32","url":"https://github.com/EdvardKS/Booking-RandomForest-Pipeline","category":"ml","description":"Pipeline de scikit-learn sobre el dataset Hotel Bookings: escalado, reducci\xf3n de dimensionalidad con PCA y clasificaci\xf3n con Random Forest. El dataset est\xe1 desbalanceado, as\xed que la lectura va por classification_report y no por accuracy.","tags":["scikit-learn","Random Forest","PCA","Pipeline","pandas"]},{"id":"booking-decisiontree","name":"Booking \xb7 \xc1rbol de decisi\xf3n","icon":"\uD83C\uDF33","url":"https://github.com/EdvardKS/Booking-DecissionTree-Pipeline","category":"ml","description":"El mismo problema atacado con otro pipeline: StandardScaler, selecci\xf3n de variables con SelectKBest y un DecisionTreeClassifier. Sirve para comparar contra el Random Forest con id\xe9ntico preprocesado.","tags":["scikit-learn","Decision Tree","SelectKBest","Pipeline","EDA"]},{"id":"booking-logistic","name":"Booking \xb7 Regresi\xf3n log\xedstica","icon":"\uD83D\uDCC8","url":"https://github.com/EdvardKS/Booking-LogisticRegression-1","category":"ml","description":"Punto de partida de la serie: exploraci\xf3n del dataset, tratamiento del desbalanceo de la variable objetivo y una regresi\xf3n log\xedstica como modelo base contra el que medir el resto.","tags":["scikit-learn","Regresi\xf3n log\xedstica","Balanceo","pandas","seaborn"]},{"id":"bigdata-etl","name":"ETL con Logstash y Kafka","icon":"\uD83D\uDEE0️","url":"https://github.com/EdvardKS/Specialization-BigdataApplied","category":"ml","description":"Especializaci\xf3n de big data aplicado: scraping de productos en Python, proceso ETL con Logstash y Kafka, y cuadros de mando sobre el resultado. Incluye la memoria del proceso completo.","tags":["Python","Logstash","Kafka","ETL","Dashboards"]},{"id":"financial-aapl","name":"An\xe1lisis financiero de AAPL","icon":"\uD83D\uDCB9","url":"https://github.com/EdvardKS/AI-Analysis-Financial-AAPL","category":"ml","description":"An\xe1lisis y predicci\xf3n sobre la serie financiera de Apple con t\xe9cnicas de inteligencia artificial. El repositorio recoge la memoria del estudio y sus conclusiones.","tags":["Series temporales","Predicci\xf3n","Finanzas","Python"]},{"id":"dl-facial","name":"Puntos faciales y emociones","icon":"\uD83D\uDE00","url":"https://github.com/EdvardKS/DeepLearning-Convulotional-FacialExpression","category":"dl","description":"Dos redes convolucionales encadenadas: la primera localiza los puntos clave de la cara por regresi\xf3n y la segunda clasifica la emoci\xf3n en cinco categor\xedas. Con aumento de datos, EarlyStopping y los pesos entrenados incluidos.","tags":["TensorFlow","Keras","CNN","Visi\xf3n artificial","Data augmentation"]},{"id":"dl-cifar10","name":"ResNet sobre CIFAR-10","icon":"\uD83D\uDDBC️","url":"https://github.com/EdvardKS/DeepLearning-Convolutional-ResNet-cifar10","category":"dl","description":"Red convolucional con arquitectura ResNet y transferencia de aprendizaje sobre CIFAR-10, de la asignatura de programaci\xf3n de inteligencia artificial en el IES Abastos.","tags":["Deep learning","ResNet","Transfer learning","CIFAR-10"]},{"id":"pytorch-flowers","name":"Clasificador de flores en PyTorch","icon":"\uD83C\uDF38","url":"https://github.com/EdvardKS/nanodegree-aws-pytorch-image-classifier","category":"dl","description":"Proyecto del nanodegree de AWS y Udacity: clasificador de im\xe1genes de flores entrenado en PyTorch y convertido despu\xe9s en una aplicaci\xf3n de l\xednea de comandos con sus argumentos de entrenamiento e inferencia.","tags":["PyTorch","CNN","Transfer learning","CLI","AWS"]},{"id":"rl-mountaincar","name":"Q-Learning \xb7 MountainCar","icon":"\uD83C\uDFD4️","url":"https://github.com/EdvardKS/Reinforced-Gym-MountainCarv0","category":"dl","description":"Aprendizaje por refuerzo sobre el entorno MountainCar-v0 de Gym: tabla Q discretizada, pol\xedtica entrenada y guardada, y la f\xf3rmula de Q-Learning explicada paso a paso en el propio cuaderno.","tags":["Reinforcement learning","Q-Learning","Gym","NumPy"]},{"id":"relbench","name":"RelBench \xb7 deep learning relacional","icon":"\uD83D\uDD78️","url":"https://github.com/EdvardKS/RelBench-BS","category":"dl","description":"Redes neuronales de grafos aplicadas directamente sobre bases de datos relacionales, sin aplanar las tablas a mano. Entrenado sobre el conjunto de Amazon con PyTorch Geometric, con el checkpoint del modelo incluido.","tags":["PyTorch Geometric","GNN","Grafos","RelBench","SQL"]},{"id":"ragasus","name":"ragasus","icon":"\uD83C\uDF63","url":"https://github.com/EdvardKS/ragasus","private":true,"category":"genai","description":"Monorepo fullstack para BI conversacional: SQL Server en solo lectura, Ollama local en la LAN y RAG con PostgreSQL + pgvector. Backend NestJS modular y frontend Next.js con App Router.","tags":["NestJS","Next.js","Ollama","pgvector","RAG","BI"]},{"id":"spark8sia","name":"spark8sia \xb7 servidor de modelos","icon":"⚡","url":"https://github.com/EdvardKS/spark8sia","private":true,"category":"genai","description":"Todo lo necesario para replicar y operar el servidor de modelos del DGX Spark: chat y visi\xf3n, coder, embeddings, imagen, v\xeddeo, base vectorial y pasarela. Pensado para levantarlo de cero desde el repositorio si la m\xe1quina se pierde.","tags":["DGX","LLM","Embeddings","Docker","Infraestructura"]},{"id":"ai-hub","name":"ai-hub","icon":"\uD83E\uDDE9","url":"https://github.com/EdvardKS/ai-hub","private":true,"category":"genai","description":"Sustituto directo del contenedor de Ollama del VPS: empaqueta el motor de inferencia y a\xf1ade una pasarela en Fastify con llamada a herramientas, cach\xe9 de prompts, selecci\xf3n de modelo y m\xe9tricas.","tags":["Ollama","Fastify","Tool calling","M\xe9tricas","Docker"]},{"id":"agentic-pdf-pipeline","name":"agentic-pdf-pipeline","icon":"\uD83D\uDCC4","url":"https://github.com/EdvardKS/agentic-pdf-pipeline","category":"genai","description":"Canalizaci\xf3n de ingesta de PDF basada en agentes, con LangGraph para la orquestaci\xf3n y CrewAI para el reparto de papeles entre ellos.","tags":["LangGraph","CrewAI","Agentes","Python","RAG"]},{"id":"agentic-rag-langgraph","name":"agentic-rag-langgraph","icon":"\uD83D\uDD01","url":"https://github.com/EdvardKS/agentic-rag-langgraph","category":"genai","description":"RAG con agentes en LangGraph: detecta y evita reprocesar duplicados por sha256 y genera manifiestos de lo ingerido, para que reindexar no signifique volver a pagar el mismo trabajo.","tags":["LangGraph","RAG","Agentes","Deduplicaci\xf3n","Python"]},{"id":"lavbotdocker","name":"LavBotDocker","icon":"\uD83E\uDD16","url":"https://github.com/EdvardKS/LavBotDocker","category":"genai","description":"Pila RAG modular y contenedorizada: canal de ingesta consciente de secciones para PDF, base vectorial Qdrant y API en FastAPI, todo levantable con Docker.","tags":["RAG","Qdrant","FastAPI","Docker","Python"]},{"id":"teriyaki","name":"teriyaki","icon":"\uD83C\uDF5C","url":"https://github.com/EdvardKS/teriyaki-v1.7","category":"genai","description":"Experimentos de RAG sobre Qdrant en cuadernos, con el foco puesto en la privacidad: el contenido no sale de la m\xe1quina que lo procesa.","tags":["RAG","Qdrant","LLM","Jupyter","Privacidad"]},{"id":"kuberagent","name":"kuberagent","icon":"☸️","url":"https://github.com/EdvardKS/kuberagent","category":"genai","description":"Agente que opera sobre Kubernetes: traduce intenciones en operaciones del cl\xfaster y devuelve el estado en lenguaje natural.","tags":["Kubernetes","Agentes","Python","DevOps"]},{"id":"coconut","name":"coconut","icon":"\uD83E\uDD65","url":"https://github.com/EdvardKS/coconut-v1.0","category":"genai","description":"Modelo de lenguaje corriendo en local con TinyLlama 1.1B cuantizado en GGUF: cu\xe1nto se puede hacer sin depender de una API externa ni de una GPU grande.","tags":["TinyLlama","GGUF","LLM local","Cuantizaci\xf3n","Python"]},{"id":"llmops-langchain","name":"LLMOps con LangChain","icon":"\uD83E\uDDEA","url":"https://github.com/EdvardKS/LLMOps-BuildRealWorldApp-LLM","category":"genai","description":"Cuadernos del curso de LLMOps: c\xf3mo llevar una aplicaci\xf3n con modelos de lenguaje del cuaderno a algo que se pueda desplegar, medir y mantener.","tags":["LLMOps","LangChain","Jupyter","Despliegue"]},{"id":"masterclass-llama","name":"Masterclass Llama 3.2 3B","icon":"\uD83E\uDD99","url":"https://github.com/EdvardKS/MasterClass-Llama323B","category":"genai","description":"Sesi\xf3n pr\xe1ctica sobre Llama 3.2 de 3B par\xe1metros: carga, ajuste y uso del modelo en cuadernos.","tags":["Llama","LLM","Jupyter","Fine-tuning"]},{"id":"ft-llama-arq","name":"ft_llama_arq","icon":"\uD83C\uDFD7️","url":"https://github.com/EdvardKS/ft_llama_arq","category":"genai","description":"Notas y arquitectura para el ajuste fino de modelos Llama: qu\xe9 capas se tocan, con qu\xe9 datos y con qu\xe9 coste.","tags":["Fine-tuning","Llama","Arquitectura"]},{"id":"justificantes-ia","name":"Lectura de justificantes con IA","icon":"\uD83E\uDDFE","url":"https://iaeks.com/casos/torneos","private":true,"category":"genai","description":"Los justificantes de transferencia que suben los jugadores de un torneo, en foto o en PDF, se leen con un modelo de lenguaje con visi\xf3n: extrae el importe, razona si cuadra con lo que deb\xeda pagar la pareja y deja el total editable para que el club lo ratifique.","tags":["Visi\xf3n","LLM","Extracci\xf3n de datos","Validaci\xf3n humana","Producci\xf3n"]},{"id":"bot-telegram-ia","name":"Bot de Telegram con IA","icon":"\uD83E\uDD16","url":"https://iaeks.com/bots-telegram-ia","private":true,"category":"genai","description":"Bot privado de Telegram conectado a un agente que opera servidores en producci\xf3n: estado de las webs, copias de seguridad e incidencias, con texto, voz, fotos y archivos. Solo obedece a usuarios emparejados y registra cada orden.","tags":["Agentes","Telegram","Ciberseguridad","Operaciones","Producci\xf3n"]},{"id":"basketclub","name":"Basket Club","icon":"\uD83C\uDFC0","url":"https://github.com/EdvardKS/basketclub","category":"web","description":"Gesti\xf3n integral de clubes de baloncesto en producci\xf3n: calendario, asistencia, partidos, mensajer\xeda, blog, biblioteca de entrenos con editor de jugadas y firma digital del RGPD. Monorepo con React 19, Express 5 y PostgreSQL.","tags":["React 19","Express 5","PostgreSQL","Drizzle","Docker"],"private":true},{"id":"chickenmanagement","name":"ChickenManagement","icon":"\uD83C\uDF57","url":"https://github.com/EdvardKS/ChickenManagement","category":"web","description":"Panel de gesti\xf3n del asador: stock en tiempo real, pedidos y caja del d\xeda.","tags":["Next.js","Express","TypeScript","Docker","Radix UI"],"private":true},{"id":"todoagricola-repo","name":"Todo Agr\xedcola","icon":"\uD83C\uDF3E","url":"https://github.com/EdvardKS/todoagricola","category":"web","description":"Tienda y cat\xe1logo agr\xedcola con panel de administraci\xf3n.","tags":["Next.js","Express","MySQL","Docker"],"private":true},{"id":"pcs-repo","name":"Padel Coaching Sergio","icon":"\uD83C\uDFBE","url":"https://github.com/EdvardKS/pcs","category":"web","description":"Web de un entrenador de p\xe1del con reservas y contenido optimizado para b\xfasqueda local.","tags":["Hono","SQLite","SEO","Docker"],"private":true},{"id":"micheck-repo","name":"MiCheck","icon":"✅","url":"https://github.com/EdvardKS/micheck","category":"web","description":"Aplicaci\xf3n web progresiva de listas de comprobaci\xf3n con funcionamiento sin conexi\xf3n y suscripciones.","tags":["PWA","SQLite","Offline","Suscripciones"],"private":true},{"id":"ailedu-repo","name":"AILEDU","icon":"\uD83D\uDCDA","url":"https://github.com/EdvardKS/ailedu","category":"web","description":"Plataforma educativa con reconocimiento \xf3ptico de caracteres y almacenamiento de objetos.","tags":["PWA","OCR","PostgreSQL","MinIO","FastAPI"],"private":true},{"id":"iaconedu-repo","name":"IA con Edu","icon":"\uD83C\uDF93","url":"https://github.com/EdvardKS/iaconedu","category":"web","description":"Sitio de divulgaci\xf3n y servicios de inteligencia artificial, con generaci\xf3n de contenido automatizada.","tags":["React","Express","PostgreSQL","Puppeteer"],"private":true},{"id":"cv-flask","name":"Este mismo sitio","icon":"\uD83D\uDDA5️","url":"https://github.com/EdvardKS/CV-Flask","category":"web","description":"El escritorio web que est\xe1s usando: ventanas, aplicaciones y curr\xedculum navegable, con asistente conectado a un modelo local.","tags":["Next.js","TypeScript","Ollama","Docker","React"],"internal":"/cv"},{"id":"gestorinmuebles","name":"Gestor de inmuebles","icon":"\uD83C\uDFE0","url":"https://github.com/EdvardKS/gestorinmuebles","category":"web","description":"Gesti\xf3n de cartera inmobiliaria: fichas de propiedades, contactos y seguimiento.","tags":["TypeScript","Next.js","PostgreSQL"],"private":true},{"id":"gestoriaeks","name":"Gestor\xeda EKS","icon":"\uD83D\uDDC2️","url":"https://github.com/EdvardKS/gestoriaeks","category":"web","description":"Generador de documentos y formularios para una gestor\xeda, con plantillas reutilizables.","tags":["TypeScript","Formularios","PDF"],"private":true},{"id":"basketball-tournaments","name":"basketballtournaments","icon":"\uD83C\uDFC6","url":"https://github.com/EdvardKS/basketballtournaments","category":"web","description":"Gesti\xf3n de torneos de baloncesto: cuadros, calendario y resultados.","tags":["Fullstack","Deporte","Torneos"]},{"id":"torneopadel","name":"Torneo P\xe1del Managment","icon":"\uD83C\uDFBE","url":"https://github.com/EdvardKS/TorneoPadelManagment","category":"web","description":"Gesti\xf3n de torneos de p\xe1del: inscripciones, cuadros y seguimiento de partidos.","tags":["TypeScript","Torneos","Docker"],"private":true},{"id":"club-connect","name":"club-connect","icon":"\uD83D\uDD17","url":"https://github.com/EdvardKS/club-connect","category":"web","description":"Conexi\xf3n entre clubes y sus socios: comunicaci\xf3n y gesti\xf3n de altas.","tags":["TypeScript","Fullstack"]},{"id":"viewersoftware","name":"viewerSoftware","icon":"\uD83D\uDCE1","url":"https://github.com/EdvardKS/viewerSoftware","category":"web","description":"Herramienta de despliegue y observaci\xf3n de los servicios del servidor.","tags":["JavaScript","Despliegue","Observabilidad"],"private":true},{"id":"miyo","name":"miyo","icon":"\uD83D\uDCF8","url":"https://github.com/EdvardKS/miyo","category":"web","description":"Red social para compartir eventos: los invitados suben sus fotos a un \xe1lbum com\xfan.","tags":["JavaScript","Social","Eventos","Fotos"]},{"id":"formularioweb","name":"FormularioWebConValidacion","icon":"\uD83D\uDCDD","url":"https://github.com/EdvardKS/FormularioWebConValidacion","category":"web","description":"Formulario web con validaci\xf3n completa en cliente, centrado en la experiencia de relleno.","tags":["Web","Validaci\xf3n","UX","Formularios"],"private":true},{"id":"elasticsearch-fullstack","name":"Elasticsearch fullstack","icon":"\uD83D\uDD0D","url":"https://github.com/EdvardKS/elasticsearch-fullstack-node-mustague","category":"web","description":"Aplicaci\xf3n de b\xfasqueda y an\xe1lisis sobre Elasticsearch, con Node en el servidor y plantillas en el cliente.","tags":["Elasticsearch","Node.js","Vue","B\xfasqueda"]},{"id":"nauticas","name":"N\xe1uticas Torrevieja","icon":"⛵","url":"https://github.com/EdvardKS/nauticas_torrevieja_app","category":"web","description":"Aplicaci\xf3n para las actividades n\xe1uticas de Torrevieja.","tags":["App","Reservas"]}]'),e=JSON.parse('[{"id":"asador","name":"Asador La Morenica","icon":"\uD83C\uDF57","image":"/assets/projects/asador/home.jpg","url":"https://asadorlamorenica.com","description":"Asador de pollos a la le\xf1a en Villena: encargos online, control de stock en tiempo real y predicci\xf3n de cu\xe1ntas barras montar.","tags":["Next.js","Astro","PostgreSQL","Redis","Docker"],"detail":{"que_es":"El negocio real de un asador de pollos a la le\xf1a, llevado a software. La parte p\xfablica recoge encargos sin obligar a crear cuenta y publica contenido local (fiestas, clima, al\xe9rgenos); la parte privada es el panel con el que se despacha el d\xeda: stock, pedidos, caja y avisos por WhatsApp.","objetivo":"Que el asador deje de apuntar los encargos en papel y sepa, antes de encender el horno, cu\xe1nto va a vender hoy.","stack":["Next.js","Astro","Express","PostgreSQL","Redis","BullMQ","Docker"],"shots":[{"src":"/assets/projects/asador/home.jpg","caption":"Portada p\xfablica. El reclamo es local y directo, sin carrusel ni pantalla de bienvenida."},{"src":"/assets/projects/asador/encargar.jpg","caption":"Encargo sin cuenta: pedir no exige registrarse, que es donde se ca\xedan los pedidos antes."},{"src":"/assets/projects/asador/fiestas.jpg","caption":"Programa de Moros y Cristianos, con los actos ratificados y su fuente oficial."},{"src":"/assets/projects/asador/clima.jpg","caption":"Clima de Villena. No es decoraci\xf3n: alimenta la predicci\xf3n de venta."},{"src":"/assets/projects/asador/alergenos.jpg","caption":"Al\xe9rgenos por producto, obligatorio por normativa y casi siempre olvidado."},{"src":"/assets/projects/asador/movil.jpg","caption":"En m\xf3vil, con los accesos a WhatsApp y tel\xe9fono siempre a mano."},{"src":"/assets/projects/asador/movil-encargar.jpg","caption":"El encargo desde el m\xf3vil, que es como llega la mayor\xeda."}],"diagram":"/assets/projects/diagrams/asador.svg","highlight":{"title":"Predice cu\xe1ntas barras montar cruzando clima y festivos","body":"Montar de m\xe1s es producto tirado; montar de menos es venta perdida y clientes que se van. El sistema guarda el hist\xf3rico de venta y lo cruza con el clima de Villena y el calendario de festivos y fiestas locales, que se sincronizan solos. Cada recomendaci\xf3n que se muestra queda registrada, y el encargado la valora corrigiendo la venta real: esa discrepancia entre lo calculado y lo que de verdad pas\xf3 es la se\xf1al con la que el modelo mejora."}}},{"id":"micheck","name":"MiCheck","icon":"✅","image":"/assets/projects/micheck/home.jpg","url":"https://miyo.edvardks.com","description":"Seguimiento de h\xe1bitos con mec\xe1nicas de videojuego: niveles, rachas y logros. Funciona sin conexi\xf3n y se instala en el m\xf3vil.","tags":["PWA","SQLite","Suscripciones","Offline"],"detail":{"que_es":"Una app para apuntar lo que quieres repetir cada d\xeda y marcarlo de un toque. Suma experiencia, sube de nivel, enciende rachas y desbloquea logros. Se instala como aplicaci\xf3n en el m\xf3vil y sigue funcionando sin cobertura.","objetivo":"Que registrar un h\xe1bito cueste menos esfuerzo que salt\xe1rselo.","stack":["PWA","Service Worker","SQLite","Node","Docker"],"shots":[{"src":"/assets/projects/micheck/home.jpg","caption":"Portada: la promesa en una frase y dos botones. Gratis, sin anuncios, en espa\xf1ol."},{"src":"/assets/projects/micheck/movil.jpg","caption":"En el m\xf3vil, que es donde se usa de verdad: se instala como app y se marca de un toque."},{"src":"/assets/projects/micheck/entrar.jpg","caption":"Acceso. La sesi\xf3n aguanta para no pedir contrase\xf1a cada d\xeda."},{"src":"/assets/projects/micheck/registro.jpg","caption":"Alta de cuenta gratuita, sin pasar por ninguna tienda de aplicaciones."},{"src":"/assets/projects/micheck/ayuda.jpg","caption":"Ayuda dentro de la propia app, explicando niveles, rachas y logros."},{"src":"/assets/projects/micheck/movil-ayuda.jpg","caption":"La misma ayuda en m\xf3vil: el contenido se reordena, no se recorta."}],"diagram":"/assets/projects/diagrams/micheck.svg","highlight":{"title":"Offline de verdad, no un cartel de \xabsin conexi\xf3n\xbb","body":"Un h\xe1bito se marca en el momento en que ocurre: en el gimnasio, en el metro, en el campo. Si la app necesita red para registrar un toque, se pierde el registro y con \xe9l la racha. Aqu\xed las marcas se guardan en el dispositivo y se sincronizan cuando vuelve la cobertura, as\xed que la app se comporta igual con red y sin ella."}}},{"id":"iaeks","name":"IA con Edu","icon":"\uD83E\uDDE0","image":"/assets/projects/iaeks/home.jpg","url":"https://iaeks.com","description":"Web de consultor\xeda en IA y datos, con un panel privado que lleva clientes, proyectos, tiempo dedicado y facturaci\xf3n.","tags":["React","Express","PostgreSQL","Puppeteer"],"detail":{"que_es":"La cara p\xfablica es una web de servicios de IA y automatizaci\xf3n. Detr\xe1s hay un panel que funciona como el sistema de gesti\xf3n del negocio: clientes, proyectos, horas dedicadas, cargos y facturas, m\xe1s el registro de visitas de la propia web.","objetivo":"Que el trabajo hecho para cada cliente quede registrado con su tiempo, y que la factura salga de ah\xed en vez de de la memoria.","stack":["React","Express","PostgreSQL","Puppeteer","Docker"],"shots":[{"src":"/assets/projects/iaeks/home.jpg","caption":"Portada p\xfablica, orientada a explicar servicios sin jerga."},{"src":"/assets/projects/iaeks/acceso.jpg","caption":"Acceso al panel privado, protegido con verificaci\xf3n anti-bot."},{"src":"/assets/projects/iaeks/casos.jpg","caption":"Casos: resultados concretos en vez de promesas gen\xe9ricas."},{"src":"/assets/projects/iaeks/proceso.jpg","caption":"El proceso de trabajo explicado paso a paso antes de contratar."},{"src":"/assets/projects/iaeks/precios.jpg","caption":"Precios p\xfablicos, que en consultor\xeda no es lo habitual."},{"src":"/assets/projects/iaeks/cursos.jpg","caption":"Formaci\xf3n, la otra pata del negocio."},{"src":"/assets/projects/iaeks/sobre-mi.jpg","caption":"Qui\xe9n est\xe1 detr\xe1s, con nombre y cara."}],"diagram":"/assets/projects/diagrams/iaeks.svg","highlight":{"title":"Fotograf\xeda sola las webs de los proyectos que gestiona","body":"El panel arranca un navegador sin interfaz dentro del propio contenedor y captura las webs de los proyectos que administra. As\xed la ficha de cada cliente muestra c\xf3mo est\xe1 su sitio hoy, no c\xf3mo estaba el d\xeda que alguien subi\xf3 una captura a mano. Es tambi\xe9n un detector de ca\xeddas: si el sitio no responde, la imagen no sale."}}},{"id":"ailedu","name":"AILEDU","icon":"\uD83D\uDCB8","image":"/assets/projects/ailedu/home.jpg","url":"https://ailedu.edvardks.com","description":"App de finanzas, calendario y tareas para parejas: paneles compartidos, OCR de tickets y avisos al m\xf3vil.","tags":["PWA","OCR","PostgreSQL","MinIO","FastAPI"],"detail":{"que_es":"Una aplicaci\xf3n para dos personas que comparten gastos y agenda. Se crean paneles compartidos, se invita por correo, y lo que se apunta en uno puede publicarse en el del otro. Los tickets se suben en foto y el sistema les saca los datos.","objetivo":"Quitar la fricci\xf3n de llevar las cuentas en com\xfan, que casi siempre acaba en una hoja de c\xe1lculo que nadie actualiza.","stack":["React","Express","PostgreSQL","MinIO","FastAPI","Web Push"],"shots":[{"src":"/assets/projects/ailedu/home.jpg","caption":"Entrada a la aplicaci\xf3n, pensada primero para m\xf3vil."},{"src":"/assets/projects/ailedu/movil.jpg","caption":"En m\xf3vil: es donde se fotograf\xeda el ticket, as\xed que es la vista que manda."}],"diagram":"/assets/projects/diagrams/ailedu.svg","highlight":{"title":"El ticket se fotograf\xeda y el gasto se rellena solo","body":"Apuntar un gasto a mano es la tarea que primero se abandona. Un servicio aparte en Python recibe la foto del ticket, le pasa reconocimiento \xf3ptico y devuelve importe y comercio para que el formulario llegue relleno. Las im\xe1genes no se guardan junto a la base de datos, sino en un almac\xe9n de objetos propio dentro del servidor, sin salir a ning\xfan servicio externo."}}},{"id":"pcs","name":"Padel Coaching Sergio","icon":"\uD83C\uDFBE","image":"/assets/projects/pcs/home.jpg","url":"https://pcs.iaeks.com","description":"Gesti\xf3n de un entrenador de p\xe1del: alumnos, bonos, clases y balance, con p\xe1ginas de captaci\xf3n por zona.","tags":["Hono","SQLite","SEO","Docker"],"detail":{"que_es":"La herramienta diaria de un entrenador de p\xe1del. Lleva alumnos, bonos de clases que se van descontando, calendario de clases, ingresos y gastos, y la deuda pendiente de cada uno. La parte p\xfablica son p\xe1ginas de captaci\xf3n por localidad.","objetivo":"Saber en cualquier momento qui\xe9n tiene bono, qui\xe9n debe y qu\xe9 se ha ingresado este mes, sin cuadernos ni notas del m\xf3vil.","stack":["Hono","SQLite","TypeScript","Docker"],"shots":[{"src":"/assets/projects/pcs/home.jpg","caption":"Portada, orientada a convertir visita en solicitud de clase."},{"src":"/assets/projects/pcs/villena.jpg","caption":"P\xe1gina por zona: Villena. Contenido propio, no la misma plantilla con la ciudad cambiada."},{"src":"/assets/projects/pcs/alicante.jpg","caption":"La misma idea para la provincia de Alicante."},{"src":"/assets/projects/pcs/login.jpg","caption":"Acceso al panel del entrenador."},{"src":"/assets/projects/pcs/movil.jpg","caption":"Versi\xf3n m\xf3vil de la portada."}],"diagram":"/assets/projects/diagrams/pcs.svg","highlight":{"title":"El bono se descuenta solo al dar la clase","body":"El error cl\xe1sico de este negocio es cobrar un bono de diez clases y perder la cuenta de cu\xe1ntas van. Aqu\xed la clase y el bono son la misma operaci\xf3n: al marcar la asistencia se descuenta el saldo, y si no queda, la deuda aparece sola en la ficha del alumno. Nadie tiene que acordarse de restar."}}},{"id":"todoagricola","name":"Todo Agr\xedcola Villena","icon":"\uD83E\uDD6C","image":"/assets/projects/todoagricola/home.jpg","url":"https://todoagricola.iaeks.com","description":"Tienda de fruta y verdura de Villena: cat\xe1logo, pedidos, suscripciones y pago online.","tags":["Next.js","Express","MySQL","Docker"],"detail":{"que_es":"El comercio de barrio con venta online. Cat\xe1logo de fruta y verdura, carrito, pedidos y suscripci\xf3n para quien quiere su cesta cada semana sin volver a pedirla.","objetivo":"Dar a una tienda local un canal de venta propio, sin depender de plataformas que se llevan comisi\xf3n y se quedan con el cliente.","stack":["Next.js 16","Express","MySQL 8.4","Docker"],"shots":[{"src":"/assets/projects/todoagricola/home.jpg","caption":"Portada de la tienda con el producto de temporada."},{"src":"/assets/projects/todoagricola/frutas.jpg","caption":"Cat\xe1logo de fruta, con el producto de temporada por delante."},{"src":"/assets/projects/todoagricola/cestas.jpg","caption":"Cestas: el formato que se convierte en suscripci\xf3n semanal."},{"src":"/assets/projects/todoagricola/despensa.jpg","caption":"Despensa, para la compra que no es fresco."},{"src":"/assets/projects/todoagricola/empresas.jpg","caption":"Canal de empresas, con condiciones distintas al particular."},{"src":"/assets/projects/todoagricola/blog.jpg","caption":"Blog de temporada: capta b\xfasquedas y sostiene el posicionamiento."},{"src":"/assets/projects/todoagricola/contacto.jpg","caption":"Contacto directo con la tienda."},{"src":"/assets/projects/todoagricola/movil.jpg","caption":"En m\xf3vil, que es por donde entra la mayor\xeda del tr\xe1fico de una tienda local."}],"diagram":"/assets/projects/diagrams/todoagricola.svg","highlight":{"title":"Solo la fachada est\xe1 expuesta; la API y la base de datos no existen desde fuera","body":"El frontal es el \xfanico contenedor conectado a la red que ve el proxy. La API y la base de datos viven en una red interna sin puerto publicado: no hay direcci\xf3n desde la que alcanzarlas aunque se conozca el servidor. Es la diferencia entre proteger la base de datos con una contrase\xf1a y que la base de datos no sea accesible en absoluto."}}},{"id":"infra","name":"Arquitectura de este servidor","icon":"\uD83D\uDDFA️","image":"/assets/projects/diagrams/infra-card.svg","url":null,"description":"C\xf3mo est\xe1 montado de verdad este servidor: un proxy, una red aislada por proyecto y un panel que lo vigila todo.","tags":["Docker","nginx","Aislamiento","Observabilidad"],"detail":{"que_es":"Este mismo servidor, contado tal y como est\xe1 hoy. Una sola m\xe1quina aloja una decena de aplicaciones independientes: un proxy reparte por dominio, cada proyecto vive en su red privada, y un panel de control centraliza despliegue, certificados, copias y vigilancia.","objetivo":"Que meter una aplicaci\xf3n m\xe1s no ponga en riesgo a las que ya est\xe1n, y que cualquier ca\xedda se vea antes de que la vea un cliente.","stack":["Docker Compose","nginx","Let\'s Encrypt","Postfix","cron"],"shots":[{"src":"/assets/projects/diagrams/infra.svg","caption":"Mapa completo: entrada por el proxy, una red por proyecto y servicios compartidos."},{"src":"/assets/projects/diagrams/infra-deploy.svg","caption":"Ciclo de despliegue: de un push en el repositorio a la versi\xf3n nueva sirviendo."},{"src":"/assets/projects/diagrams/infra-vigilancia.svg","caption":"Qu\xe9 se vigila, cada cu\xe1nto, y qu\xe9 se corrige solo cuando algo falla."}],"diagram":"/assets/projects/diagrams/infra.svg","highlight":{"title":"Aislamiento por red, no por confianza","body":"Cada proyecto tiene su propia red privada de contenedores. Su base de datos no publica ning\xfan puerto: solo existe para los contenedores de su propio proyecto. El proxy es el \xfanico que habla con el exterior, y solo alcanza al contenedor que hace de fachada de cada aplicaci\xf3n. La consecuencia pr\xe1ctica es que si una aplicaci\xf3n se ve comprometida, el atacante aparece en una red donde no hay nada de las dem\xe1s: ni bases de datos vecinas, ni servicios internos, ni credenciales de otros proyectos."}}},{"id":"panel","name":"Panel de control de infraestructura","icon":"\uD83D\uDEE0️","image":"/assets/projects/panel.svg","url":null,"private_panel":true,"description":"Aplicaci\xf3n privada que despliega, renueva certificados, vigila y avisa. Sin acceso p\xfablico, y sin publicar su direcci\xf3n.","tags":["Node","Docker","Observabilidad","2FA"],"detail":{"que_es":"La aplicaci\xf3n desde la que se opera el servidor: despliegue de cada proyecto, renovaci\xf3n de certificados, copias de seguridad, estado de los contenedores, cola de correo y alertas. Es privada, con doble factor, y no se publica ni su direcci\xf3n ni su interfaz.","objetivo":"Reunir en un sitio las operaciones que, si no, se hacen por consola, a mano y con riesgo de equivocarse.","stack":["Node","API de Docker","SQLite","TOTP","WebSocket"],"shots":[],"diagram":"/assets/projects/diagrams/infra-vigilancia.svg","highlight":{"title":"Deliberadamente sin capturas ni direcci\xf3n publicada","body":"Un panel que despliega, edita configuraci\xf3n y reinicia contenedores es la llave del servidor. Publicar su aspecto, sus rutas o su dominio le ahorra a un atacante justo el trabajo de reconocimiento que m\xe1s cuesta. Aqu\xed se cuenta lo que hace, porque es la parte interesante, y se omite todo lo que ayudar\xeda a encontrarlo o a atacarlo. La seguridad no depende de ese silencio, pero tampoco hay motivo para regalar el mapa."}}},{"id":"smtp","name":"Relay de correo propio","icon":"✉️","image":"/assets/projects/smtp.svg","url":null,"description":"Postfix con firma DKIM que env\xeda el correo de todas las apps del servidor sin depender de un proveedor externo.","tags":["Postfix","OpenDKIM","SPF/DMARC"],"detail":{"que_es":"Un servicio de env\xedo de correo compartido por todas las aplicaciones del servidor. Solo env\xeda, nunca recibe. Firma cada mensaje para que los buzones de destino lo acepten como leg\xedtimo.","objetivo":"Que ninguna aplicaci\xf3n tenga que llevar credenciales de un proveedor de correo, ni sus avisos acaben en spam.","stack":["Postfix","OpenDKIM","SPF","DMARC","Docker"],"shots":[],"diagram":"/assets/projects/smtp.svg","highlight":{"title":"Las apps no guardan ninguna credencial de correo","body":"Las aplicaciones env\xedan a un servicio que solo existe dentro de la red interna, sin usuario ni contrase\xf1a, porque no es alcanzable desde fuera. Las claves de firma viven en un \xfanico sitio en lugar de repartidas por diez ficheros de configuraci\xf3n. Si ma\xf1ana cambia el proveedor de salida, se cambia en un servicio y no en diez aplicaciones."}}},{"id":"ia","name":"IA local","icon":"\uD83E\uDD16","image":"/assets/projects/ia.svg","url":null,"description":"Pasarela de modelos de lenguaje ejecut\xe1ndose en el propio servidor, compartida por varias aplicaciones.","tags":["Ollama","Fastify","SQLite"],"detail":{"que_es":"Un servicio que ejecuta modelos de lenguaje dentro del servidor y los ofrece a las dem\xe1s aplicaciones por una \xfanica puerta, con cach\xe9, m\xe9tricas y equivalencias entre modelos.","objetivo":"Usar modelos de lenguaje sin enviar los datos de los clientes a un tercero ni pagar por consulta.","stack":["Ollama","Fastify","SQLite","Docker"],"shots":[],"diagram":"/assets/projects/ia.svg","highlight":{"title":"Los datos no salen de la m\xe1quina","body":"Cuando el texto que procesa un modelo son pedidos, facturas o datos personales de clientes, mandarlo a un servicio de terceros es una cesi\xf3n de datos que hay que justificar y declarar en la pol\xedtica de privacidad. Ejecutando el modelo en el propio servidor esa cesi\xf3n no existe. Adem\xe1s, una capa intermedia traduce nombres de modelos y reutiliza respuestas repetidas, para que las aplicaciones no dependan de qu\xe9 modelo est\xe9 instalado hoy."}}}]'),f={ml:{title:"Machine learning y ciencia de datos",blurb:"Datos reales, pipelines de scikit-learn y modelos que se leen por su matriz de confusi\xf3n, no por su accuracy."},dl:{title:"Deep learning",blurb:"Redes convolucionales, grafos y aprendizaje por refuerzo, entrenados de principio a fin."},genai:{title:"IA generativa y agentes",blurb:"RAG, agentes y modelos de lenguaje corriendo en local y en producci\xf3n."},web:{title:"Web y aplicaciones",blurb:"Producto: lo que la gente usa cada d\xeda."},infra:{title:"Infraestructura",blurb:"Lo que sostiene todo lo dem\xe1s: servidor, despliegues, correo y modelos en local."}},g=["ml","dl","genai","web","infra"],h=[...d.map(function(a){var b;let c=a.url.startsWith("https://github.com/");return{slug:a.id,name:a.name,icon:a.icon,discipline:"ml"===(b=a.category)||"dl"===b||"genai"===b||"web"===b?a.category:"web",description:a.description,tags:a.tags,repoUrl:c&&!a.private?a.url:null,liveUrl:c?null:a.url,image:null,whatItIs:null,goal:null,stack:[],shots:[],highlight:null}}),...e.map(function(a){return{slug:a.id,name:a.name,icon:a.icon,discipline:a.url?"web":"infra",description:a.description,tags:a.tags,repoUrl:null,liveUrl:a.url,image:a.image,whatItIs:a.detail?.que_es??null,goal:a.detail?.objetivo??null,stack:a.detail?.stack??[],shots:a.detail?.shots??[],highlight:a.detail?.highlight??null}})];function i(a){return h.find(b=>b.slug===a)}function j(a){return h.filter(b=>b.discipline===a)}function k(a){return`/projects/${a}`}}};